 function library(seed,added=[]){const rows=new Map();for(const item of seed){const original=typeof item==='string'?item:item.text,text=concise(original),k=key(text);if(!text)continue;if(!rows.has(k))rows.set(k,{text,kind:'jacob_generalized',original_texts:[]});rows.get(k).original_texts.push(original);}for(const item of added){const original=clean(typeof item==='string'?item:item.text),text=concise(original),k=key(text);if(text&&!rows.has(k))rows.set(k,{text,kind:'reviewer_added',original_texts:[]});}return [...rows.values()].sort((a,b)=>a.text.localeCompare(b.text));}
